-- Generated by scripts/generate-seed.ts from the sample catalogue. Do not edit by hand.
-- Removes the SAMPLE products that came with the starter catalogue from a LIVE database. It is not a migration and never runs
-- by itself. Read docs/REMOVE_SAMPLE_DATA.md first, and take a Supabase backup before running it for real.
--
-- What it does, for the sample products only (matched by their web address):
--   * a sample product nobody has ever ordered is deleted, with its sizes, photos, stock and reviews;
--   * a sample product that appears on a customer's order is only hidden from the shop (so order history, receipts and returns
--     keep working). Take it off the Inventory page later by writing its stock off if you want the counts to read zero.
-- It changes nothing else: orders, customers, categories, delivery settings and any product you added yourself are untouched.
--
-- It ends with ROLLBACK, so the first run is a dry run that only prints what would happen. To apply it, change the last line
-- from "rollback;" to "commit;" and run it again.

begin;

create temporary table sample_slugs (slug text primary key) on commit drop;
insert into sample_slugs (slug) values
    ('gentle-baby-wash-shampoo'),
    ('vitamin-c-brightening-serum'),
    ('whipped-shea-body-butter'),
    ('velvet-matte-lip-colour'),
    ('organic-cotton-bodysuits'),
    ('wooden-stacking-blocks'),
    ('wooden-number-puzzle'),
    ('newborn-gift-hamper'),
    ('argan-hair-oil'),
    ('shea-cocoa-body-butter');

create temporary table sample_products on commit drop as
select p.id, p.slug, p.name,
       exists (select 1 from public.order_items oi where oi.product_id = p.id) as ordered
from public.products p
join sample_slugs s on s.slug = p.slug;

select count(*) filter (where not ordered) as will_be_deleted,
       count(*) filter (where ordered)     as will_be_hidden_only,
       count(*)                            as sample_products_found,
       (select count(*) from public.products) as products_in_shop_now
from sample_products;

-- Sample products that are on real orders: hide them from the shop.
update public.products set is_published = false where id in (select id from sample_products where ordered);
delete from public.merchandising_slots where product_id in (select id from sample_products);

-- Never-ordered sample products: remove their stock history first (it is kept even for deleted products otherwise), then the products.
delete from public.stock_receipts where product_id in (select id from sample_products where not ordered);
delete from public.stock_movements where product_id in (select id from sample_products where not ordered);
delete from public.stock_batches where product_id in (select id from sample_products where not ordered);
delete from public.products where id in (select id from sample_products where not ordered);

select (select count(*) from public.products) as products_left_in_shop,
       (select count(*) from public.products where is_published) as published_products_left;

rollback;
